-- ---------------------------------------------------------------------------
-- Hand-written from here down. Prisma cannot model these, and each one is an
-- invariant that must hold for every writer, not only for the domain functions
-- that check them today (CLAUDE.md, the business-line contract s.5).
-- ---------------------------------------------------------------------------

-- 1. Keys are immutable. A code change is a new line plus a 100% successor,
--    never an edit: the code is how a line is named across history.
CREATE OR REPLACE FUNCTION business_lines_guard_keys() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NEW."id" IS DISTINCT FROM OLD."id"
     OR NEW."tenantId" IS DISTINCT FROM OLD."tenantId"
     OR NEW."code" IS DISTINCT FROM OLD."code" THEN
    RAISE EXCEPTION 'business_lines: id, tenantId and code are immutable; a code change is a new line with a 100 percent successor'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "business_lines_guard_keys"
  BEFORE UPDATE ON "business_lines"
  FOR EACH ROW EXECUTE FUNCTION business_lines_guard_keys();

-- 2. A dated row ends after it starts. A NULL end is open-ended.
ALTER TABLE "business_lines"
  ADD CONSTRAINT "business_lines_dates_ordered"
  CHECK ("effectiveTo" IS NULL OR "effectiveTo" > "effectiveFrom");

ALTER TABLE "line_distributions"
  ADD CONSTRAINT "line_distributions_dates_ordered"
  CHECK ("effectiveTo" IS NULL OR "effectiveTo" > "effectiveFrom");

-- 3. Successors: no line succeeds itself, and a share is 1..10000 or absent.
ALTER TABLE "business_line_successors"
  ADD CONSTRAINT "business_line_successors_distinct_lines"
  CHECK ("fromLineId" <> "toLineId");

ALTER TABLE "business_line_successors"
  ADD CONSTRAINT "business_line_successors_share_range"
  CHECK ("shareBasisPoints" IS NULL OR "shareBasisPoints" BETWEEN 1 AND 10000);

-- A split states a share on every successor or on none, and the stated shares
-- total 10000. Deferred, so the rows of one split may be written in one
-- transaction in any order.
CREATE OR REPLACE FUNCTION business_line_successors_check_split() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  n      bigint;
  stated bigint;
  total  bigint;
BEGIN
  SELECT count(*), count("shareBasisPoints"), coalesce(sum("shareBasisPoints"), 0)
    INTO n, stated, total
    FROM business_line_successors
   WHERE "tenantId" = NEW."tenantId"
     AND "fromLineId" = NEW."fromLineId"
     AND "effectiveFrom" = NEW."effectiveFrom";
  IF stated NOT IN (0, n) THEN
    RAISE EXCEPTION 'business_line_successors: a split states its basis points on every successor or on none';
  END IF;
  IF stated = n AND n > 0 AND total <> 10000 THEN
    RAISE EXCEPTION 'business_line_successors: a split of basis points must total 10000, got %', total;
  END IF;
  RETURN NULL;
END
$$;

CREATE CONSTRAINT TRIGGER "business_line_successors_split"
  AFTER INSERT OR UPDATE ON "business_line_successors"
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION business_line_successors_check_split();

-- 4. A distribution names exactly one subject, and no subject has two
--    distributions covering the same day. The subject is COALESCE of the three
--    columns, which is well defined because exactly one is set.
ALTER TABLE "line_distributions"
  ADD CONSTRAINT "line_distributions_one_subject"
  CHECK (num_nonnulls("costCentreId", "ledgerCategoryId", "transactionId") = 1);

ALTER TABLE "line_distributions"
  ADD CONSTRAINT "line_distributions_no_overlap"
  EXCLUDE USING gist (
    "tenantId" WITH =,
    (COALESCE("costCentreId", "ledgerCategoryId", "transactionId")) WITH =,
    daterange("effectiveFrom", "effectiveTo", '[)') WITH &&
  );

-- 5. Shares: each is 1..10000, and a distribution's shares total 10000 at
--    commit. A header with no lines fails the same check.
ALTER TABLE "line_distribution_lines"
  ADD CONSTRAINT "line_distribution_lines_share_range"
  CHECK ("basisPoints" BETWEEN 1 AND 10000);

CREATE OR REPLACE FUNCTION line_distributions_check_total() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  did   text;
  n     bigint;
  total bigint;
BEGIN
  IF TG_TABLE_NAME = 'line_distributions' THEN
    did := NEW."id";
  ELSIF TG_OP = 'DELETE' THEN
    did := OLD."distributionId";
  ELSE
    did := NEW."distributionId";
  END IF;
  -- A line removed together with its whole distribution in one transaction
  -- leaves nothing to total. A line removed while its header stays is refused.
  IF TG_TABLE_NAME = 'line_distribution_lines'
     AND NOT EXISTS (SELECT 1 FROM line_distributions WHERE "id" = did) THEN
    RETURN NULL;
  END IF;
  SELECT count(*), coalesce(sum("basisPoints"), 0)
    INTO n, total
    FROM line_distribution_lines
   WHERE "distributionId" = did;
  IF n = 0 OR total <> 10000 THEN
    RAISE EXCEPTION 'line_distributions: shares must total 10000 basis points, got % over % lines', total, n;
  END IF;
  RETURN NULL;
END
$$;

CREATE CONSTRAINT TRIGGER "line_distributions_total_on_header"
  AFTER INSERT ON "line_distributions"
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION line_distributions_check_total();

CREATE CONSTRAINT TRIGGER "line_distributions_total_on_line"
  AFTER INSERT OR UPDATE OR DELETE ON "line_distribution_lines"
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION line_distributions_check_total();

-- 6. An OrgUnit is a line unit with a line, a function unit with none, or an
--    unclassified unit with neither (every row that predates the registry).
ALTER TABLE "org_units"
  ADD CONSTRAINT "org_units_line_or_function"
  CHECK (
    ("kind" IS NULL AND "businessLineId" IS NULL)
    OR ("kind" = 'line' AND "businessLineId" IS NOT NULL)
    OR ("kind" = 'function' AND "businessLineId" IS NULL)
  );

-- 7. Row-level security on the new tables. The tenant_rls migration sorts after
--    this one and would cover them too; the explicit policies make this
--    migration correct on its own, including on a database where tenant_rls
--    has already run.
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['business_lines', 'business_line_successors', 'line_distributions', 'line_distribution_lines']
  LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format('DROP POLICY IF EXISTS "tenant_isolation" ON %I', t);
    EXECUTE format(
      'CREATE POLICY "tenant_isolation" ON %I '
      'USING ("tenantId" = current_setting(''app.tenant_id'', true)) '
      'WITH CHECK ("tenantId" = current_setting(''app.tenant_id'', true))',
      t
    );
  END LOOP;
END
$$;

-- 8. The application role may use the new tables. Guarded: on a fresh database
--    the role is created by tenant_rls, which grants on every table anyway.
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'kaizen_app') THEN
    GRANT SELECT, INSERT, UPDATE, DELETE ON "business_lines", "business_line_successors", "line_distributions", "line_distribution_lines" TO "kaizen_app";
  END IF;
END
$$;
